-- RA (Rebirth Assistant) schema for Supabase Postgres. Generated by `python -m app.cli print-ddl`.
-- The app creates these itself on startup (init_db); this file is for review.
CREATE SCHEMA IF NOT EXISTS "mf";
SET search_path TO "mf";

CREATE TABLE audit_log (
	id VARCHAR(32) NOT NULL, 
	actor_type VARCHAR(16) NOT NULL, 
	actor_id VARCHAR(32), 
	action VARCHAR(60) NOT NULL, 
	entity_name VARCHAR(40) NOT NULL, 
	entity_id VARCHAR(64), 
	payload JSON, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE category_stat (
	id VARCHAR(32) NOT NULL, 
	category_key VARCHAR(40) NOT NULL, 
	as_of DATE NOT NULL, 
	model_version VARCHAR(20) NOT NULL, 
	stats JSON NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (category_key, as_of, model_version)
);

CREATE INDEX ix_category_stat_category_key ON category_stat (category_key);

CREATE TABLE document (
	id VARCHAR(32) NOT NULL, 
	source VARCHAR(20) NOT NULL, 
	doc_type VARCHAR(30) NOT NULL, 
	title VARCHAR(300) NOT NULL, 
	url TEXT NOT NULL, 
	published_on DATE, 
	fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	mime VARCHAR(80), 
	bytes INTEGER NOT NULL, 
	storage_path TEXT NOT NULL, 
	pages INTEGER, 
	amc_name VARCHAR(120), 
	amfi_code INTEGER, 
	text_chars INTEGER NOT NULL, 
	meta JSON, 
	PRIMARY KEY (id), 
	UNIQUE (url)
);

CREATE INDEX ix_document_doc_type ON document (doc_type);

CREATE TABLE investor (
	id VARCHAR(32) NOT NULL, 
	display_name VARCHAR(120) NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE scheme (
	amfi_code INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	amc_name VARCHAR(120) NOT NULL, 
	raw_category VARCHAR(160) NOT NULL, 
	category_key VARCHAR(40) NOT NULL, 
	plan_type VARCHAR(12) NOT NULL, 
	option_type VARCHAR(12) NOT NULL, 
	isin_growth VARCHAR(12), 
	isin_reinvest VARCHAR(12), 
	latest_nav NUMERIC(14, 4), 
	latest_nav_date DATE, 
	riskometer VARCHAR(20) NOT NULL, 
	riskometer_source VARCHAR(20) NOT NULL, 
	in_universe BOOLEAN NOT NULL, 
	is_benchmark_proxy BOOLEAN NOT NULL, 
	nav_history_synced_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (amfi_code)
);

CREATE INDEX ix_scheme_category_key ON scheme (category_key);
CREATE INDEX ix_scheme_name ON scheme (name);
CREATE INDEX ix_scheme_amc_name ON scheme (amc_name);
CREATE INDEX ix_scheme_isin_reinvest ON scheme (isin_reinvest);
CREATE INDEX ix_scheme_isin_growth ON scheme (isin_growth);
CREATE INDEX ix_scheme_in_universe ON scheme (in_universe);

CREATE TABLE scheme_detail (
	amfi_code INTEGER NOT NULL, 
	amc_full_name VARCHAR(160), 
	scheme_base_name VARCHAR(255), 
	scheme_type VARCHAR(40), 
	scheme_category VARCHAR(160), 
	nav_name VARCHAR(255), 
	min_amount NUMERIC(18, 2), 
	launch_date DATE, 
	closure_date DATE, 
	isins JSON, 
	raw JSON NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (amfi_code)
);

CREATE INDEX ix_scheme_detail_scheme_base_name ON scheme_detail (scheme_base_name);

CREATE TABLE scheme_link (
	amfi_code INTEGER NOT NULL, 
	source VARCHAR(20) NOT NULL, 
	external_key VARCHAR(120) NOT NULL, 
	method VARCHAR(20) NOT NULL, 
	score FLOAT NOT NULL, 
	PRIMARY KEY (amfi_code, source)
);

CREATE INDEX ix_scheme_link_external_key ON scheme_link (external_key);

CREATE TABLE scheme_performance (
	id VARCHAR(32) NOT NULL, 
	external_key VARCHAR(120) NOT NULL, 
	plan VARCHAR(12) NOT NULL, 
	amfi_code INTEGER, 
	scheme_name VARCHAR(255) NOT NULL, 
	as_of DATE NOT NULL, 
	benchmark VARCHAR(255), 
	riskometer VARCHAR(30), 
	benchmark_riskometer VARCHAR(30), 
	aum_cr FLOAT, 
	returns JSON, 
	benchmark_returns JSON, 
	raw JSON NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (external_key, plan, as_of)
);

CREATE INDEX ix_scheme_performance_external_key ON scheme_performance (external_key);
CREATE INDEX ix_scheme_performance_amfi_code ON scheme_performance (amfi_code);

CREATE TABLE scheme_ter (
	id VARCHAR(32) NOT NULL, 
	nsdl_code VARCHAR(40) NOT NULL, 
	mf_id INTEGER, 
	scheme_name VARCHAR(255) NOT NULL, 
	scheme_category VARCHAR(160), 
	scheme_type VARCHAR(40), 
	effective_from DATE NOT NULL, 
	r_ber FLOAT, 
	r_brokerage FLOAT, 
	r_transaction FLOAT, 
	r_statutory FLOAT, 
	r_ter FLOAT, 
	d_ber FLOAT, 
	d_brokerage FLOAT, 
	d_transaction FLOAT, 
	d_statutory FLOAT, 
	d_ter FLOAT, 
	r_6a_b FLOAT, 
	r_6a_c FLOAT, 
	d_6a_b FLOAT, 
	d_6a_c FLOAT, 
	PRIMARY KEY (id), 
	UNIQUE (nsdl_code, effective_from)
);

CREATE INDEX ix_scheme_ter_nsdl_code ON scheme_ter (nsdl_code);

CREATE TABLE source_file (
	id VARCHAR(32) NOT NULL, 
	amc_name VARCHAR(120) NOT NULL, 
	disclosure_month DATE NOT NULL, 
	kind VARCHAR(20) NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	source_url TEXT NOT NULL, 
	via VARCHAR(10) NOT NULL, 
	stored_path TEXT NOT NULL, 
	registered_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (sha256)
);

CREATE INDEX ix_source_file_amc_name ON source_file (amc_name);

CREATE TABLE chat_session (
	id VARCHAR(32) NOT NULL, 
	investor_id VARCHAR(32) NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	system_prompt TEXT NOT NULL, 
	prompt_version VARCHAR(20) NOT NULL, 
	model VARCHAR(40) NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(investor_id) REFERENCES investor (id) ON DELETE CASCADE
);

CREATE INDEX ix_chat_session_investor_id ON chat_session (investor_id);

CREATE TABLE document_chunk (
	id VARCHAR(32) NOT NULL, 
	document_id VARCHAR(32) NOT NULL, 
	seq INTEGER NOT NULL, 
	page_from INTEGER, 
	page_to INTEGER, 
	heading VARCHAR(300), 
	text TEXT NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (document_id, seq), 
	FOREIGN KEY(document_id) REFERENCES document (id) ON DELETE CASCADE
);

CREATE INDEX ix_document_chunk_document_id ON document_chunk (document_id);

CREATE TABLE nav_history (
	amfi_code INTEGER NOT NULL, 
	nav_date DATE NOT NULL, 
	nav NUMERIC(14, 4) NOT NULL, 
	PRIMARY KEY (amfi_code, nav_date), 
	FOREIGN KEY(amfi_code) REFERENCES scheme (amfi_code)
);

CREATE TABLE scheme_metric (
	id VARCHAR(32) NOT NULL, 
	amfi_code INTEGER NOT NULL, 
	as_of DATE NOT NULL, 
	model_version VARCHAR(20) NOT NULL, 
	metrics JSON NOT NULL, 
	composite_score FLOAT, 
	tier VARCHAR(12), 
	PRIMARY KEY (id), 
	UNIQUE (amfi_code, as_of, model_version), 
	FOREIGN KEY(amfi_code) REFERENCES scheme (amfi_code)
);

CREATE INDEX ix_scheme_metric_amfi_code ON scheme_metric (amfi_code);

CREATE TABLE scheme_portfolio (
	id VARCHAR(32) NOT NULL, 
	amfi_code INTEGER NOT NULL, 
	disclosure_month DATE NOT NULL, 
	security_isin VARCHAR(12), 
	security_name VARCHAR(160) NOT NULL, 
	sector VARCHAR(80), 
	industry VARCHAR(120), 
	asset_class VARCHAR(20), 
	weight_pct FLOAT NOT NULL, 
	market_value_inr FLOAT, 
	quantity FLOAT, 
	rating VARCHAR(40), 
	source_url TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(amfi_code) REFERENCES scheme (amfi_code)
);

CREATE INDEX ix_scheme_portfolio_security_isin ON scheme_portfolio (security_isin);
CREATE INDEX ix_scheme_portfolio_amfi_code ON scheme_portfolio (amfi_code);

CREATE TABLE chat_message (
	id VARCHAR(32) NOT NULL, 
	session_id VARCHAR(32) NOT NULL, 
	seq INTEGER NOT NULL, 
	role VARCHAR(12) NOT NULL, 
	api_content JSON NOT NULL, 
	display_text TEXT, 
	visible BOOLEAN NOT NULL, 
	tool_calls JSON, 
	guardrail JSON, 
	disclosures JSON, 
	model VARCHAR(40), 
	prompt_version VARCHAR(20), 
	usage JSON, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (session_id, seq), 
	FOREIGN KEY(session_id) REFERENCES chat_session (id) ON DELETE CASCADE
);

CREATE INDEX ix_chat_message_session_id ON chat_message (session_id);

CREATE TABLE escalation (
	id VARCHAR(32) NOT NULL, 
	investor_id VARCHAR(32) NOT NULL, 
	session_id VARCHAR(32), 
	category VARCHAR(40) NOT NULL, 
	reason TEXT NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(investor_id) REFERENCES investor (id) ON DELETE CASCADE, 
	FOREIGN KEY(session_id) REFERENCES chat_session (id) ON DELETE SET NULL
);

CREATE INDEX ix_escalation_investor_id ON escalation (investor_id);

